package cn.blockforge.generated.generatedmod;

import java.util.*;
import cn.blockforge.generated.generatedmod.alchemy.simulation.*;
import static cn.blockforge.generated.generatedmod.alchemy.simulation.SimulationRules.*;
import static cn.blockforge.generated.generatedmod.alchemy.simulation.AlchemySimulation.*;

/** Independent integer examples, not expected results generated by the engine itself. */
public final class AlchemySimulationRegression {
    private static int checks;
    private static void check(boolean condition,String message){checks++;if(!condition)throw new AssertionError(message);}
    private static void rejects(Runnable action){boolean rejected=false;try{action.run();}catch(IllegalArgumentException|ArithmeticException expected){rejected=true;}check(rejected,"Invalid input accepted");}
    private static Limits limits(int noise,int extent,long pressure){return new Limits(32,extent,100,256,1000000,100000,10,1000000,10000,10000000,pressure,noise);}
    private static List<Resource> resources(){return List.of(new Resource("cold",1,1,0,Destination.ACTIVE),new Resource("hot",1,1,0,Destination.ACTIVE),new Resource("mediator",1,0,0,Destination.ACTIVE),new Resource("product",1,1,0,Destination.ACTIVE),new Resource("residue",1,0,0,Destination.RESIDUE),new Resource("gas",1,1,1000,Destination.ACTIVE));}
    private static Reaction reaction(String id,int priority,Map<String,Long> in,Map<String,Long> out,int hold,List<Window> windows){return new Reaction(id,priority,Phase.WARMUP,in,out,1000,0,0,hold,windows);}
    private static SimulationRules rules(List<Reaction> reactions){return new SimulationRules("reference-1",resources(),reactions,limits(0,1000,Long.MAX_VALUE));}
    private static Snapshot start(SimulationRules r,Map<String,Long> stocks,long heat,long reference){return begin(r,"test",stocks,heat,reference,987,Map.of("humidity",50L));}
    private static Operation op(Snapshot s,Action a,String resource,long amount){return new Operation(s.lastSequence()+1,s.tick(),a,resource,amount);}
    public static void main(String[] args){run();}
    public static void run(){
        var combine=reaction("combine",0,Map.of("cold",2L,"hot",2L,"mediator",1L),Map.of("product",3L,"residue",2L),1,List.of());
        var r=rules(List.of(combine));var initial=start(r,Map.of("cold",10L,"hot",8L,"mediator",3L),0,21);
        var result=step(r,initial,List.of()).snapshot();
        check(result.stocks().equals(Map.of("cold",4L,"hot",2L,"product",9L,"residue",6L)),"Hand calculation: three extents, mass 21, potential 18 -> 15 + loss 3");
        check(result.ledger().initialMass()==21&&result.ledger().lostPotential()==3&&r.weight(result.stocks(),false)==15,"Three accounts must not conflate loss of potential and loss of mass");
        check(initial.stocks().get("cold")==10,"Input immutable");
        check(step(r,start(r,Map.of(),0,1),List.of()).snapshot().stocks().isEmpty(),"Empty input must not invent output");
        rejects(()->start(r,Map.of("unknown",1L),0,1));rejects(()->start(r,Map.of("cold",-1L),0,1));
        rejects(()->rules(List.of(reaction("bad",0,Map.of("cold",1L),Map.of("product",2L),1,List.of()))));
        rejects(()->rules(List.of(reaction("bad",0,Map.of("mediator",1L),Map.of("product",1L),1,List.of()))));
        var a=reaction("a",0,Map.of("cold",1L),Map.of("product",1L),1,List.of());
        var b=reaction("b",0,Map.of("cold",1L),Map.of("residue",1L),1,List.of());
        var ab=rules(List.of(a,b));var ba=rules(List.of(b,a));
        check(ab.hash.equals(ba.hash),"Rule declaration order cannot change snapshot identity");
        var competed=step(ab,start(ab,Map.of("cold",7L),0,7),List.of());
        check(competed.snapshot().stocks().equals(Map.of("product",7L))&&competed.reactions().size()==1,"Stable priority/id allocation prevents resource double spend");
        var reverse=reaction("reverse",1,Map.of("product",1L),Map.of("cold",1L),1,List.of());
        var loop=rules(List.of(a,reverse));var state=start(loop,Map.of("cold",5L),0,5);
        check(step(loop,state,List.of()).snapshot().stocks().equals(Map.of("product",5L)),"New product participates next step only");
        for(int i=0;i<101;i++)state=step(loop,state,List.of()).snapshot();
        check(state.status()==Status.PAUSED&&state.reason().equals("STEP_BUDGET")&&loop.weight(state.stocks(),false)==5,"Cycles bounded without gain");
        var narrow=rules(List.of(new Reaction("limited",0,Phase.WARMUP,Map.of("cold",1L),Map.of("product",1L),1000,0,0,1,List.of())));
        var capped=new SimulationRules("cap",resources(),narrow.reactions,limits(0,2,Long.MAX_VALUE));
        var cap=step(capped,start(capped,Map.of("cold",5L),0,5),List.of()).snapshot();
        check(cap.status()==Status.PAUSED&&cap.stocks().get("product")==2&&cap.stocks().get("cold")==3,"Extent budget preserves partial progress and inventory");
        var windows=List.of(new Window(Measure.CONCENTRATION_PPM,"cold",750000,1000000),new Window(Measure.CONCENTRATION_PPM,"hot",750000,1000000),new Window(Measure.RATIO_PPM,"cold","hot",980000,1020000),new Window(Measure.TEMPERATURE,"",490,510),new Window(Measure.ENVIRONMENT,"humidity",40,60));
        var structured=rules(List.of(reaction("structure",0,Map.of("cold",750L,"hot",750L,"mediator",200L),Map.of("product",1500L,"residue",200L),40,windows),reaction("break",1,Map.of("product",3L),Map.of("residue",3L),1,List.of(new Window(Measure.TEMPERATURE,"",511,10000)))));
        state=start(structured,Map.of("cold",800L,"hot",800L,"mediator",200L),5000,1000);
        for(int i=0;i<39;i++)state=step(structured,state,List.of()).snapshot();
        check(!state.stocks().containsKey("product"),"Hold cannot form early");state=step(structured,state,List.of()).snapshot();
        check(state.stocks().get("product")==1500,"Absolute stocks, ratio, mediator, environment, temperature and hold jointly required");
        state=step(structured,state,List.of(op(state,Action.HEAT,"",200))).snapshot();
        check(!state.stocks().containsKey("product")&&state.ledger().lostPotential()==1500,"Formed structure can break");
        for(long heat:new long[]{4899,5101}){state=start(structured,Map.of("cold",800L,"hot",800L,"mediator",200L),heat,1000);for(int i=0;i<41;i++)state=step(structured,state,List.of()).snapshot();check(!state.stocks().containsKey("product"),"Rational temperature boundary must not round into window");}
        state=start(structured,Map.of("cold",800L,"hot",800L,"mediator",199L),5000,1000);for(int i=0;i<41;i++)state=step(structured,state,List.of()).snapshot();check(!state.stocks().containsKey("product"),"Balanced net value without mediator cannot form structure");
        var noisy=new SimulationRules("noise",resources(),List.of(),limits(3,1000,Long.MAX_VALUE));state=start(noisy,Map.of("cold",1L),0,1);
        for(int i=0;i<50;i++){
            var bytes=SimulationSnapshotCodec.encodeServerSnapshot(noisy,state);var restored=SimulationSnapshotCodec.decodeServerSnapshot(noisy,bytes);check(restored.equals(state),"Snapshot exact round trip");
            sample(987,"preview",i);var events=List.of(op(state,Action.HEAT,"",10));var one=step(noisy,state,events).snapshot();var two=step(noisy,restored,events).snapshot();check(one.equals(two),"Save/reload and observer sampling cannot reroll");
            long added=one.ledger().externalEnergy()-state.ledger().externalEnergy();check(added>=7&&added<=13,"Source jitter bounded and actual energy accounted");state=one;
        }
        var saved=SimulationSnapshotCodec.encodeServerSnapshot(noisy,state);rejects(()->SimulationSnapshotCodec.decodeServerSnapshot(r,saved));rejects(()->SimulationSnapshotCodec.decodeServerSnapshot(noisy,Arrays.copyOf(saved,saved.length-1)));rejects(()->SimulationSnapshotCodec.decodeServerSnapshot(noisy,Arrays.copyOf(saved,saved.length+1)));
        var unchanged=state;rejects(()->step(noisy,unchanged,List.of(new Operation(0,unchanged.tick(),Action.HEAT,"",1))));
        rejects(()->step(noisy,unchanged,List.of(op(unchanged,Action.ENVIRONMENT,"unknown",10))));
        var dangerous=new SimulationRules("danger",resources(),List.of(),new Limits(32,1000,100,256,1000000,100000,10,1000000,1,1,1,0));
        var accident=step(dangerous,start(dangerous,Map.of("gas",4L),100,4),List.of()).snapshot();
        check(accident.status()==Status.EXPLODED&&accident.stocks().isEmpty()&&accident.ledger().ashMass()==3&&accident.ledger().ventedMass()==1,"Pressure wins simultaneous accident; all mass accounted once");
        check(step(dangerous,accident,List.of()).snapshot().equals(accident),"Terminal accident idempotent");
        var gasCleanup=reaction("cleanup",0,Map.of("gas",1L),Map.of("residue",1L),1,List.of());
        var hidden=new SimulationRules("peak",resources(),List.of(gasCleanup),dangerous.limits);
        check(step(hidden,start(hidden,Map.of("gas",4L),100,4),List.of()).snapshot().status()==Status.EXPLODED,"Reaction cannot erase pre-reaction dangerous pressure");
        var funded=new SimulationRules("funded",resources(),List.of(new Reaction("bind",0,Phase.WARMUP,Map.of("mediator",1L),Map.of("product",1L),1,2,1,1,List.of())),limits(0,1000,Long.MAX_VALUE));
        var bound=step(funded,start(funded,Map.of("mediator",1L),10,1),List.of()).snapshot();
        check(bound.heat()==8&&bound.ledger().boundEnergy()==2&&bound.ledger().authorizedPotential()==1,"Potential gain requires explicitly bound external energy");
        var noEnergy=step(funded,start(funded,Map.of("mediator",1L),1,1),List.of()).snapshot();check(noEnergy.stocks().containsKey("mediator"),"Unfunded reaction cannot run");
        for(Map<String,Long> wrong:List.of(Map.of("cold",700L,"hot",700L,"mediator",200L),Map.of("cold",900L,"hot",750L,"mediator",200L))){
            var s=start(structured,wrong,5000,1000);for(int i=0;i<41;i++)s=step(structured,s,List.of()).snapshot();check(!s.stocks().containsKey("product"),"Net balance or high quantity cannot bypass absolute concentration and ratio window");
        }
        var counts=new int[7];for(int i=0;i<10000;i++)counts[(int)Math.floorMod(sample(123,"control",i),7)]++;
        for(int count:counts)check(count>1100&&count<1800,"Bounded random stream has gross distribution bias");
        var abort=start(noisy,Map.of("cold",1L),100,1);abort=step(noisy,abort,List.of(op(abort,Action.ABORT,"",0))).snapshot();check(abort.status()==Status.ABORTED&&abort.heat()==0&&abort.ledger().ventedEnergy()==100&&abort.stocks().get("cold")==1,"Abort retains material and records released energy");
        for(int n=1;n<200;n++){var s=start(r,Map.of("cold",n*2L,"hot",n*2L,"mediator",(long)n),0,5L*n);s=step(r,s,List.of()).snapshot();check(s.ledger().lostPotential()==n&&r.weight(s.stocks(),true)==5L*n,"Scaled amount changes inventory, not a free quality or mass bonus");}
        System.out.println("AlchemySimulation independent checks: "+checks);
    }
}
